import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Define block and tile sizes
#define BLOCK_SIZE 16

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Shared memory for A_sub and B_sub
    __shared__ float A_shared[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float B_shared[BLOCK_SIZE][BLOCK_SIZE];

    // Each thread computes one element of the C matrix
    float C_value = 0.0f;

    // Loop over tiles
    int num_tiles = (N + BLOCK_SIZE - 1) / BLOCK_SIZE;
    for (int t = 0; t < num_tiles; ++t) {
        // Load A_sub and B_sub into shared memory
        int row_A = by * BLOCK_SIZE + ty;
        int col_A = t * BLOCK_SIZE + tx;
        if (row_A < N && col_A < N) {
            A_shared[ty][tx] = A[row_A * N + col_A];
        } else {
            A_shared[ty][tx] = 0.0f; // Pad with zeros if out of bounds
        }

        int row_B = t * BLOCK_SIZE + ty;
        int col_B = bx * BLOCK_SIZE + tx;
        if (row_B < N && col_B < N) {
            B_shared[ty][tx] = B[row_B * N + col_B];
        } else {
            B_shared[ty][tx] = 0.0f; // Pad with zeros if out of bounds
        }
        __syncthreads();

        // Perform computation on the tile
        for (int k = 0; k < BLOCK_SIZE; ++k) {
            C_value += A_shared[ty][k] * B_shared[k][tx];
        }
        __syncthreads();
    }

    // Write result to global memory
    int row_C = by * BLOCK_SIZE + ty;
    int col_C = bx * BLOCK_SIZE + tx;
    if (row_C < N && col_C < N) {
        C[row_C * N + col_C] = C_value;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block_dim(BLOCK_SIZE, BLOCK_SIZE);
    dim3 grid_dim((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (N + BLOCK_SIZE - 1) / BLOCK_SIZE);

    matmul_kernel<<<grid_dim, block_dim>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

matmul_cpp_source = (
    "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code for matrix multiplication
matmul = load_inline(
    name="matmul_kernel_module",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_cuda_func = matmul.matmul_cuda

    def forward(self, A, B):
        return self.matmul_cuda_func(A, B)
